//! Code-walk blocks in lesson Markdown, and the staleness check over them.
//!
//! A lesson marks a walk with an opening comment holding the walk's
//! parameters and any hops filled in by hand, followed by the generated
//! output and a closing comment:
//!
//! ```text
//! <!-- code-walk: from=crates/x/examples/demo.rs::main to=crates/x/src/geom.rs::Sphere::distance
//! hand: crates/x/src/keff.rs::step -> crates/x/src/geom.rs::Sphere::distance | Geometry::distance dispatch; Godiva is a Sphere
//! -->
//! ...generated by kovan-cli code-walk-check --update; never edited by hand...
//! <!-- /code-walk -->
//! ```
//!
//! Keys on the first line: `from=` (required), `to=` (path mode; omit for
//! the exhaustive tree), `depth=`, `format=markdown|mermaid|both`,
//! `max-paths=`. Each `hand:` line is `<from> -> <to> | <note>`: a hop the
//! tool marked `UNRESOLVED(...)` and a person or lesson-writing agent filled
//! after reading the code. The opening comment is never rewritten, so hand
//! hops survive every regeneration; the tool only replaces what sits between
//! the two comments.
//!
//! The check (`kovan-cli code-walk-check <paths>`) regenerates every block
//! and fails when the output differs from what is committed (a hop moved,
//! appeared or disappeared), when a concept path no longer connects, or when
//! a hand-filled hop names a function that no longer exists.
//! `--update` writes the regenerated output instead of failing on a
//! difference; it still fails on a broken chain or a vanished hand hop.

use std::path::{Path, PathBuf};

use super::builder::HandHop;
use super::{Format, WalkSpec};

pub(crate) const OPEN: &str = "<!-- code-walk:";
pub(crate) const CLOSE: &str = "<!-- /code-walk -->";

/// One block found in a Markdown file.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Block {
    pub(crate) spec: WalkSpec,
    /// Byte range of the opening comment, `<!--` through `-->`.
    pub(crate) header: (usize, usize),
    /// Byte range of the generated body (between the comments), and whether
    /// a closing comment was found.
    pub(crate) body: (usize, usize),
    pub(crate) closed: bool,
    /// 1-based line of the opening comment, for messages.
    pub(crate) line: usize,
}

/// Parses the header text between `<!-- code-walk:` and `-->`.
pub(crate) fn parse_header(text: &str) -> Result<WalkSpec, String> {
    let mut lines = text.lines();
    let first = lines.next().unwrap_or("");
    let mut spec = WalkSpec::default();
    for tok in first.split_whitespace() {
        let Some((k, v)) = tok.split_once('=') else {
            return Err(format!("expected key=value, got `{tok}`"));
        };
        match k {
            "from" => spec.from = v.to_string(),
            "to" => spec.to = Some(v.to_string()),
            "depth" => {
                spec.depth = Some(v.parse().map_err(|_| format!("bad depth `{v}`"))?)
            }
            "max-paths" => {
                spec.max_paths = v.parse().map_err(|_| format!("bad max-paths `{v}`"))?
            }
            "format" => {
                spec.format = match v {
                    "markdown" => Format::Markdown,
                    "mermaid" => Format::Mermaid,
                    "both" => Format::Both,
                    _ => return Err(format!("format must be markdown|mermaid|both, got `{v}`")),
                }
            }
            _ => return Err(format!("unknown key `{k}`")),
        }
    }
    for l in lines {
        let l = l.trim();
        if l.is_empty() {
            continue;
        }
        let Some(rest) = l.strip_prefix("hand:") else {
            return Err(format!("unexpected line in code-walk header: `{l}`"));
        };
        spec.hand.push(parse_hand(rest)?);
    }
    if spec.from.is_empty() {
        return Err("missing from=".to_string());
    }
    Ok(spec)
}

/// `A -> B | note` (the note is optional).
pub(crate) fn parse_hand(s: &str) -> Result<HandHop, String> {
    let (hop, note) = match s.split_once('|') {
        Some((h, n)) => (h, n.trim()),
        None => (s, ""),
    };
    let Some((a, b)) = hop.split_once("->") else {
        return Err(format!("hand hop `{}` is not `<from> -> <to> | <note>`", s.trim()));
    };
    Ok(HandHop {
        from: a.trim().to_string(),
        to: b.trim().to_string(),
        note: note.to_string(),
    })
}

/// Every code-walk block in `text`.
pub(crate) fn find_blocks(text: &str) -> Result<Vec<Block>, String> {
    let mut out = Vec::new();
    let mut at = 0;
    while let Some(i) = text[at..].find(OPEN) {
        let start = at + i;
        let line = text[..start].matches('\n').count() + 1;
        let hdr_from = start + OPEN.len();
        let Some(j) = text[hdr_from..].find("-->") else {
            return Err(format!("line {line}: unterminated `{OPEN}` comment"));
        };
        let hdr_end = hdr_from + j + 3;
        let spec = parse_header(&text[hdr_from..hdr_from + j])
            .map_err(|e| format!("line {line}: {e}"))?;
        let next_open = text[hdr_end..].find(OPEN).map(|k| hdr_end + k);
        let close = text[hdr_end..].find(CLOSE).map(|k| hdr_end + k);
        let (body, closed, resume) = match close {
            Some(c) if next_open.is_none_or(|n| c < n) => ((hdr_end, c), true, c + CLOSE.len()),
            _ => ((hdr_end, hdr_end), false, hdr_end),
        };
        out.push(Block {
            spec,
            header: (start, hdr_end),
            body,
            closed,
            line,
        });
        at = resume;
    }
    Ok(out)
}

/// Every `.md` file under `paths` (files are taken as given), sorted.
pub(crate) fn markdown_files(paths: &[PathBuf]) -> Vec<PathBuf> {
    let mut out = Vec::new();
    for p in paths {
        collect(p, &mut out);
    }
    out.sort();
    out.dedup();
    out
}

fn collect(p: &Path, out: &mut Vec<PathBuf>) {
    if p.is_file() {
        out.push(p.to_path_buf());
    } else if let Ok(rd) = std::fs::read_dir(p) {
        for e in rd.flatten() {
            let path = e.path();
            let name = e.file_name();
            let name = name.to_string_lossy();
            if path.is_dir() {
                if name != "target" && name != "book" && !name.starts_with('.') {
                    collect(&path, out);
                }
            } else if name.ends_with(".md") {
                out.push(path);
            }
        }
    }
}

/// A short line diff for a failed check: lines only in the committed block
/// (`-`) and lines only in the regenerated one (`+`), at most `max` each.
pub(crate) fn line_diff(old: &str, new: &str, max: usize) -> String {
    let old_l: Vec<&str> = old.lines().collect();
    let new_l: Vec<&str> = new.lines().collect();
    let mut out = String::new();
    for l in old_l.iter().filter(|l| !new_l.contains(l)).take(max) {
        out.push_str(&format!("    - {l}\n"));
    }
    for l in new_l.iter().filter(|l| !old_l.contains(l)).take(max) {
        out.push_str(&format!("    + {l}\n"));
    }
    out
}

/// The text that goes between the comments for `generated` output.
pub(crate) fn body_text(generated: &str) -> String {
    format!(
        "\n<!-- generated by `kovan-cli code-walk-check --update`; edit the comment above, not this -->\n\n{}\n",
        generated.trim_end()
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    const LESSON: &str = "# Lesson\n\nText.\n\n<!-- code-walk: from=crates/a/examples/m.rs::main to=crates/a/src/k.rs::Sphere::distance depth=8 format=both\nhand: crates/a/src/k.rs::step -> crates/a/src/k.rs::Sphere::distance | trait dispatch; Godiva is a Sphere\n-->\nold body\n<!-- /code-walk -->\n\nMore.\n\n<!-- code-walk: from=crates/a/src/k.rs::step depth=2 -->\n";

    /// Methodology: a lesson with one closed path block carrying a hand hop
    /// and one unclosed tree block.
    ///
    /// Result (2026-10-04): both parsed; keys, the hand hop and its note,
    /// and the closed/unclosed state are as written.
    #[test]
    fn finds_blocks_with_parameters_and_hand_hops() {
        let b = find_blocks(LESSON).unwrap();
        assert_eq!(b.len(), 2);
        let s = &b[0].spec;
        assert_eq!(s.from, "crates/a/examples/m.rs::main");
        assert_eq!(s.to.as_deref(), Some("crates/a/src/k.rs::Sphere::distance"));
        assert_eq!(s.depth, Some(8));
        assert_eq!(s.format, Format::Both);
        assert_eq!(
            s.hand,
            vec![HandHop {
                from: "crates/a/src/k.rs::step".into(),
                to: "crates/a/src/k.rs::Sphere::distance".into(),
                note: "trait dispatch; Godiva is a Sphere".into(),
            }]
        );
        assert!(b[0].closed);
        assert_eq!(LESSON[b[0].body.0..b[0].body.1].trim(), "old body");
        assert_eq!(b[0].line, 5);
        assert!(!b[1].closed);
        assert_eq!(b[1].spec.to, None);
        assert_eq!(b[1].spec.depth, Some(2));
    }

    /// Methodology: malformed headers must be rejected with a message, not
    /// silently ignored (a typo'd key would otherwise drop a constraint).
    ///
    /// Result (2026-10-04): passes.
    #[test]
    fn rejects_malformed_headers() {
        assert!(parse_header("to=a.rs::f").is_err());
        assert!(parse_header("from=a.rs::f dpeth=3").is_err());
        assert!(parse_header("from=a.rs::f\nhand: a.rs::f b.rs::g").is_err());
        assert!(parse_header("from=a.rs::f\nnote: x").is_err());
    }

    /// Methodology: a removed hop line and an added one appear as `-`/`+`.
    ///
    /// Result (2026-10-04): passes.
    #[test]
    fn diff_reports_removed_and_added_lines() {
        let d = line_diff("a\nb\nc\n", "a\nc\nd\n", 10);
        assert_eq!(d, "    - b\n    + d\n");
    }
}
